public class RateLimitHandlerapply_ConsumptionProbegetRemainingTokensFikaTest {

    @Test
    public void testApplyInvokesGetRemainingTokens() throws Exception {
        // Create a real ConsumptionProbe that will return true for isConsumed()
        ConsumptionProbe probe = Mockito.mock(ConsumptionProbe.class);
        Mockito.when(probe.isConsumed()).thenReturn(true);
        Mockito.when(probe.getRemainingTokens()).thenReturn(5L);

